158	static sal_spp_connection_t* spp_find_connection_by_scn(const bt_address_t* addr, uint16_t scn)
159	{
160	    sal_spp_manager_t* spp_mgr = &g_spp_manager;
161	    sal_spp_connection_t* spp_conn;
162	    bt_list_node_t* node;
163	
164	    if (!spp_mgr->connections || !addr) {
165	        return NULL;
166	    }
167	
168	    for (node = bt_list_head(spp_mgr->connections); node != NULL;
169	         node = bt_list_next(spp_mgr->connections, node)) {
170	        spp_conn = bt_list_node(node);
171	        if (spp_conn->scn == scn && bt_addr_compare(&spp_conn->addr, addr) == 0) {
172	            return spp_conn;
173	        }
174	    }
175	
176	    return NULL;
177	}
