287	struct bt_sdp_record* spp_sdp_create_record(uint16_t channel, bt_uuid_t* uuid)
288	{
289	    spp_sdp_record_t* spp_record;
290	    size_t attrs_count;
291	
292	    if (!uuid) {
293	        BT_LOGE("Invalid uuid");
294	        return NULL;
295	    }
296	
297	    spp_record = zalloc(sizeof(spp_sdp_record_t));
298	    if (!spp_record) {
299	        BT_LOGE("Failed to allocate memory for SPP SDP value with uuid");
300	        return NULL;
301	    }
302	
303	    spp_record->attrs = zalloc(sizeof(spp_attrs_template));
304	    if (!spp_record->attrs) {
305	        BT_LOGE("Failed to allocate memory for SPP SDP attributes with uuid");
306	        free(spp_record);
307	        return NULL;
308	    }
309	
310	    attrs_count = ARRAY_SIZE(spp_attrs_template);
311	    memcpy(spp_record->attrs, spp_attrs_template, sizeof(spp_attrs_template));
312	
313	    memcpy(spp_record->uuid128, uuid->val.u128, BT_UUID_SIZE_128);
314	    spp_record->channel = channel;
315	
316	    for (int i = 0; i < attrs_count; i++) {
317	        if (spp_record->attrs[i].id == BT_SDP_ATTR_SVCLASS_ID_LIST) {
318	            spp_record->svclass_id_list[0] = (struct bt_sdp_data_elem) {
319	                BT_SDP_TYPE_SIZE(BT_SDP_UUID128),
320	                .data = spp_record->uuid128,
321	            };
322	
323	            spp_record->attrs[i].val.data = spp_record->svclass_id_list;
324	        } else if (spp_record->attrs[i].id == BT_SDP_ATTR_PROTO_DESC_LIST) {
325	            struct bt_sdp_data_elem* list_tmpl = (struct bt_sdp_data_elem*)spp_record->attrs[i].val.data;
326	            struct bt_sdp_data_elem* rfcomm_tmpl = NULL;
327	
328	            if (!list_tmpl) {
329	                BT_LOGE("SPP Descriptor List PROTO_DESC is NULL");
330	                goto fail;
331	            }
332	
333	            spp_record->proto_desc_list[0] = list_tmpl[0];
334	            spp_record->proto_desc_list[1] = list_tmpl[1];
335	
336	            rfcomm_tmpl = (struct bt_sdp_data_elem*)spp_record->proto_desc_list[1].data;
337	            if (!rfcomm_tmpl) {
338	                BT_LOGE("SPP Descriptor List Channel is NULL");
339	                goto fail;
340	            }
341	
342	            spp_record->proto_desc_rfcomm[0] = rfcomm_tmpl[0];
343	            spp_record->proto_desc_rfcomm[1] = rfcomm_tmpl[1];
344	            spp_record->proto_desc_rfcomm[1].data = &spp_record->channel;
345	
346	            spp_record->proto_desc_list[1].data = spp_record->proto_desc_rfcomm;
347	            spp_record->attrs[i].val.data = spp_record->proto_desc_list;
348	        }
349	    }
350	
351	    spp_record->record.attr_count = attrs_count;
352	    spp_record->record.attrs = spp_record->attrs;
353	
354	    return &spp_record->record;
355	
356	fail:
357	    free(spp_record->attrs);
358	    free(spp_record);
359	    return NULL;
360	}
