370	static void spp_rfcomm_connected(struct bt_rfcomm_dlc* rfcomm_dlc)
371	{
372	    sal_spp_connection_t* spp_conn;
373	
374	    BT_LOGD("%s, rfcomm_dlc: %p", __func__, rfcomm_dlc);
375	
376	    bt_rfcomm_dlc_set_rx_credit_mode(rfcomm_dlc, BT_RFCOMM_RX_CREDIT_MANUAL);
377	
378	    spp_conn_lock();
379	    spp_conn = spp_find_connection_by_dlc(rfcomm_dlc);
380	    if (!spp_conn) {
381	        spp_conn_unlock();
382	        BT_LOGE("SPP connection not found for rfcomm_dlc");
383	        return;
384	    }
385	
386	    spp_on_connection_state_changed(&spp_conn->addr, spp_conn->conn_port, PROFILE_STATE_CONNECTED);
387	    spp_on_connection_mfs_update(spp_conn->conn_port, rfcomm_dlc->mtu);
388	
389	    bt_sal_cm_profile_connected_callback(&spp_conn->addr, PROFILE_SPP, spp_conn->conn_port);
390	    bt_sal_profile_disconnect_register(&spp_conn->addr, PROFILE_SPP, spp_conn->conn_port, PRIMARY_ADAPTER, spp_disconnect_handler, spp_conn);
391	
392	    spp_conn_unlock();
393	}
