435	static void spp_rfcomm_recv(struct bt_rfcomm_dlc* rfcomm_dlc, struct net_buf* buf)
436	{
437	    sal_spp_connection_t* spp_conn;
438	
439	    BT_DUMPBUFFER("SPP RX:", buf->data, buf->len);
440	
441	    spp_conn_lock();
442	    spp_conn = spp_find_connection_by_dlc(rfcomm_dlc);
443	    if (!spp_conn) {
444	        spp_conn_unlock();
445	        BT_LOGE("SPP connection not found for rfcomm_dlc");
446	        return;
447	    }
448	
449	    bt_list_add_tail(spp_conn->rx_list, net_buf_ref(buf));
450	    spp_on_data_received(&spp_conn->addr, spp_conn->conn_port, buf->data, buf->len);
451	    spp_conn_unlock();
452	}
