454	static void spp_rfcomm_sent(struct bt_rfcomm_dlc* rfcomm_dlc, int err)
455	{
456	    sal_spp_connection_t* spp_conn;
457	
458	    if (err < 0) {
459	        BT_LOGE("Failed to send data on RFCOMM rfcomm_dlc %p, error: %d", rfcomm_dlc, err);
460	        return;
461	    }
462	
463	    spp_conn_lock();
464	    spp_conn = spp_find_connection_by_dlc(rfcomm_dlc);
465	    if (!spp_conn) {
466	        spp_conn_unlock();
467	        BT_LOGE("SPP connection not found for rfcomm_dlc");
468	        return;
469	    }
470	
471	    bt_list_remove_node(spp_conn->tx_list, bt_list_head(spp_conn->tx_list));
472	    spp_conn_unlock();
473	}
