482	static void spp_tx_clean(void* data)
483	{
484	    sal_spp_buffer_t* tx_buf = (sal_spp_buffer_t*)data;
485	
486	    if (!tx_buf) {
487	        return;
488	    }
489	
490	    /* Notify SPP service that data has been sent */
491	    spp_on_data_sent(tx_buf->conn_port, tx_buf->buf, 0, 0);
492	    free(tx_buf);
