504	static void spp_connection_free(void* data)
505	{
506	    sal_spp_connection_t* spp_conn = (sal_spp_connection_t*)data;
507	
508	    if (!data) {
509	        return;
510	    }
511	
512	    if (spp_conn->tx_list) {
513	        bt_list_free(spp_conn->tx_list);
514	    }
515	
516	    if (spp_conn->rx_list) {
517	        bt_list_free(spp_conn->rx_list);
518	    }
519	
520	    if (spp_conn->conn) {
521	        bt_conn_unref(spp_conn->conn);
522	        spp_conn->conn = NULL;
523	    }
524	
525	    if (spp_conn->spp_client) {
526	        free(spp_conn->spp_client);
527	        spp_conn->spp_client = NULL;
528	    }
529	
530	    free(spp_conn);
531	}
