567	static int spp_rfcomm_accept(struct bt_conn* conn, struct bt_rfcomm_server* server, struct bt_rfcomm_dlc** rfcomm_dlc)
568	{
569	    bt_address_t addr;
570	    bt_status_t status;
571	    sal_spp_connection_t* spp_conn;
572	    sal_spp_manager_t* spp_mgr = &g_spp_manager;
573	    sal_spp_server_t* spp_server = CONTAINER_OF(server, sal_spp_server_t, rfcomm_server);
574	
575	    status = bt_sal_get_remote_address(conn, &addr);
576	    if (status != BT_STATUS_SUCCESS) {
577	        BT_LOGE("Failed to get remote address, error: %d", status);
578	        return -ENXIO;
579	    }
580	
581	    spp_conn = spp_connection_new(&addr, 0, server->channel);
582	    if (!spp_conn) {
583	        BT_LOGE("Failed to create SPP connection for DLCI %d", server->channel);
584	        return -ENOMEM;
585	    }
586	
587	    spp_conn->spp_server = spp_server;
588	    spp_conn->conn = conn;
589	    bt_conn_ref(conn);
590	
591	    spp_conn_lock();
592	    bt_list_add_tail(spp_mgr->connections, spp_conn);
593	    *rfcomm_dlc = &spp_conn->rfcomm_dlc;
594	    spp_conn_unlock();
595	
596	    spp_on_server_recieve_connect_request(&addr, STACK_SVR_PORT(server->channel));
597	
598	    BT_LOGD("RFCOMM DLC accept, dlci: %d", server->channel);
599	
600	    return 0;
601	}
