652	bt_status_t bt_sal_spp_server_start(uint16_t port, bt_uuid_t* uuid, uint8_t max_connection)
653	{
654	    sal_spp_manager_t* spp_mgr = &g_spp_manager;
655	    sal_spp_server_t* server;
656	    uint16_t scn = PORT2SCN(port);
657	    int ret;
658	
659	    if (scn < BT_RFCOMM_CHAN_SPP || scn > 30) {
660	        BT_LOGE("Invalid port number: %d", port);
661	        return BT_STATUS_PARM_INVALID;
662	    }
663	
664	    server = zalloc(sizeof(sal_spp_server_t));
665	    if (!server) {
666	        return BT_STATUS_NOMEM;
667	    }
668	
669	    server->scn = scn;
670	    server->rfcomm_server.channel = scn;
671	    server->rfcomm_server.accept = spp_rfcomm_accept;
672	    ret = bt_rfcomm_server_register(&server->rfcomm_server);
673	    if (ret < 0) {
674	        BT_LOGE("Failed to register RFCOMM server: %d", ret);
675	        free(server);
676	        return BT_STATUS_FAIL;
677	    }
678	
679	    server->sdp_record = (struct bt_sdp_record*)spp_sdp_create_record(scn, uuid);
680	    ret = bt_sdp_register_service(server->sdp_record);
681	    if (ret < 0) {
682	        BT_LOGE("Failed to register SDP record: %d", ret);
683	        bt_rfcomm_server_unregister(&server->rfcomm_server);
684	        spp_sdp_remove_record(server->sdp_record);
685	        free(server);
686	        return BT_STATUS_FAIL;
687	    }
688	
689	    bt_list_add_tail(spp_mgr->servers, server);
690	    BT_LOGD("SDP record registered for RFCOMM server on channel %d", scn);
691	
692	    return BT_STATUS_SUCCESS;
693	}
