739	static uint8_t sdp_discovered_cb(struct bt_conn* conn, struct bt_sdp_client_result* result,
740	    const struct bt_sdp_discover_params* param)
741	{
742	    int err;
743	    uint8_t ret = BT_SDP_DISCOVER_UUID_STOP;
744	    uint16_t scn;
745	    sal_spp_connection_t* spp_conn;
746	
747	    spp_conn = spp_find_connection_by_sdp_param(conn, param);
748	    if (!spp_conn) {
749	        BT_LOGE("SPP connection not found for conn");
750	        return BT_SDP_DISCOVER_UUID_STOP;
751	    }
752	
753	    if (!result->resp_buf) {
754	        BT_LOGE("SPP SDP discover response buffer is null");
755	        ret = BT_SDP_DISCOVER_UUID_CONTINUE;
756	        goto fail;
757	    }
758	
759	    err = bt_sdp_get_proto_param(result->resp_buf, BT_SDP_PROTO_RFCOMM, &scn);
760	    if (err < 0) {
761	        BT_LOGE("Failed to get RFCOMM channel from SDP response: %d", err);
762	        ret = BT_SDP_DISCOVER_UUID_CONTINUE;
763	        goto fail;
764	    }
765	
766	    BT_LOGD("SPP SDP record found: scn=%d", scn);
767	
768	    err = spp_connect_with_channel(spp_conn, scn);
769	    if (err < 0) {
770	        BT_LOGE("SPP connect RFCOMM fail, err:%d", err);
771	        ret = BT_SDP_DISCOVER_UUID_STOP;
772	        goto fail;
773	    }
774	
775	    spp_conn->spp_client->discovered = true;
776	    return BT_SDP_DISCOVER_UUID_STOP;
777	
778	fail:
779	    spp_conn->spp_client->discovered = false;
780	    return ret;
781	}
