783	static void sdp_disconnected_cb(struct bt_conn* conn, const struct bt_sdp_discover_params* param)
784	{
785	    sal_spp_connection_t* spp_conn;
786	    sal_spp_client_t* spp_client;
787	
788	    spp_conn = spp_find_connection_by_sdp_param(conn, param);
789	    if (!spp_conn) {
790	        BT_LOGE("SPP connection not found for conn");
791	        return;
792	    }
793	
794	    BT_LOGD("SPP SDP discover disconnected");
795	    spp_client = spp_conn->spp_client;
796	    if (!spp_client) {
797	        BT_LOGE("SPP client not found for conn");
798	        return;
799	    }
800	
801	    if (spp_client->discovered == false) {
802	        spp_rfcomm_disconnected(&spp_conn->rfcomm_dlc);
803	    }
804	}
