806	static bt_status_t spp_connect_with_uuid(sal_spp_connection_t* spp_conn, bt_uuid_t* uuid)
807	{
808	    sal_spp_client_t* spp_client;
809	    int err;
810	    bt_uuid_t uuid_128;
811	
812	    if (!spp_conn || !uuid) {
813	        BT_LOGE("Invalid parameters: spp_conn=%p, uuid=%p", spp_conn, uuid);
814	        return BT_STATUS_PARM_INVALID;
815	    }
816	
817	    spp_client = spp_conn->spp_client;
818	    if (!spp_client) {
819	        BT_LOGE("SPP client not found for conn");
820	        return BT_STATUS_PARM_INVALID;
821	    }
822	
823	    sys_memcpy_swap(uuid_128.val.u128, uuid->val.u128, sizeof(uuid->val.u128));
824	
825	    err = bt_uuid_create((struct bt_uuid*)&spp_client->uuid_128, uuid_128.val.u128, BT_UUID_SIZE_128);
826	    if (err < 0) {
827	        BT_LOGE("Failed to create UUID: %d", err);
828	        return err;
829	    }
830	
831	    spp_client->sdp_discover.func = sdp_discovered_cb;
832	    spp_client->sdp_discover.disconnected = sdp_disconnected_cb;
833	    spp_client->sdp_discover.type = BT_SDP_DISCOVER_SERVICE_SEARCH_ATTR;
834	    spp_client->sdp_discover.pool = &sdp_pool;
835	    spp_client->sdp_discover.uuid = (const struct bt_uuid*)&spp_client->uuid_128;
836	
837	    err = bt_sdp_discover(spp_conn->conn, &spp_client->sdp_discover);
838	    if (err < 0) {
839	        BT_LOGE("Failed to discover service: %d", err);
840	        return err;
841	    }
842	
843	    return 0;
844	}
