894	bt_status_t bt_sal_spp_connect(bt_address_t* addr, uint16_t conn_port, bt_uuid_t* uuid)
895	{
896	    sal_spp_connection_t* spp_conn;
897	    uint16_t scn = PORT2SCN(conn_port);
898	    char addr_str[BT_ADDR_STR_LENGTH] = { 0 };
899	    char uuid_str[BT_UUID_STR_LENGTH] = { 0 };
900	    sal_spp_client_t* spp_client;
901	    bt_status_t status;
902	
903	    if (!addr || scn > 30) {
904	        BT_LOGE("Invalid parameters: addr=%p, scn=%d", addr, scn);
905	        return BT_STATUS_PARM_INVALID;
906	    }
907	
908	    bt_addr_ba2str(addr, addr_str);
909	    bt_uuid_to_string(uuid, uuid_str, BT_UUID_STR_LENGTH);
910	    BT_LOGD("%s, addr:%s, scn:%d, uuid:%s", __func__, addr_str, scn, uuid_str);
911	
912	    spp_conn_lock();
913	
914	    /* check connection exists */
915	    spp_conn = spp_find_connection_by_port(conn_port);
916	    if (!spp_conn && (conn_port & 0x3F)) {
917	        spp_conn = spp_find_connection_by_dlci(addr, PORT2DLCI(conn_port, 0));
918	    }
919	
920	    if (spp_conn) {
921	        spp_conn_unlock();
922	        BT_LOGE("SPP connection already exists for port %d", conn_port);
923	        return BT_STATUS_BUSY;
924	    }
925	
926	    spp_conn_unlock();
927	
928	    /* create spp connection object */
929	    spp_conn = spp_connection_new((bt_address_t*)addr, conn_port, scn);
930	    if (!spp_conn) {
931	        BT_LOGE("Failed to allocate memory for SPP connection");
932	        return BT_STATUS_NOMEM;
933	    }
934	
935	    spp_client = zalloc(sizeof(sal_spp_client_t));
936	    if (!spp_client) {
937	        spp_connection_free(spp_conn);
938	        return BT_STATUS_NOMEM;
939	    }
940	
941	    spp_conn->spp_client = spp_client;
942	    memcpy(&spp_conn->uuid, uuid, sizeof(bt_uuid_t));
943	
944	    status = bt_sal_profile_connect_request(&spp_conn->addr, PROFILE_SPP, spp_conn->conn_port, PRIMARY_ADAPTER, spp_connect_handler, spp_conn);
945	    if (status != BT_STATUS_SUCCESS) {
946	        BT_LOGE("Failed to connect SPP, status: %d", status);
947	        spp_connection_free(spp_conn);
948	        return BT_STATUS_FAIL;
949	    }
950	
951	    return BT_STATUS_SUCCESS;
952	}
