954	static bt_status_t spp_disconnect_handler(bt_controller_id_t id, bt_address_t* bd_addr, void* user_data)
955	{
956	    struct bt_rfcomm_dlc* rfcomm_dlc = (struct bt_rfcomm_dlc*)user_data;
957	    sal_spp_connection_t* spp_conn;
958	    int ret;
959	
960	    BT_LOGD("%s, rfcomm_dlc: %p", __func__, rfcomm_dlc);
961	
962	    spp_conn_lock();
963	    spp_conn = spp_find_connection_by_dlc(rfcomm_dlc);
964	    if (!spp_conn) {
965	        spp_conn_unlock();
966	        BT_LOGE("SPP connection not found for rfcomm_dlc");
967	        return BT_STATUS_FAIL;
968	    }
969	
970	    spp_conn_unlock();
971	
972	    /* Disconnect the RFCOMM DLC */
973	    ret = bt_rfcomm_dlc_disconnect(&spp_conn->rfcomm_dlc);
974	    if (ret < 0) {
975	        BT_LOGE("Failed to disconnect RFCOMM DLC: %d", ret);
976	        return BT_STATUS_FAIL;
977	    }
978	
979	    return BT_STATUS_SUCCESS;
980	}
