1024	bt_status_t bt_sal_spp_write(uint16_t conn_port, uint8_t* buf, uint16_t size)
1025	{
1026	    sal_spp_connection_t* spp_conn;
1027	    struct net_buf* nbuf = NULL;
1028	    sal_spp_buffer_t* spp_buf;
1029	    int ret;
1030	
1031	    spp_conn_lock();
1032	    spp_conn = spp_find_connection_by_port(conn_port);
1033	    if (!spp_conn) {
1034	        spp_conn_unlock();
1035	        BT_LOGE("No SPP connection found for port %d", conn_port);
1036	        return BT_STATUS_PARM_INVALID;
1037	    }
1038	
1039	    spp_conn_unlock();
1040	
1041	    nbuf = net_buf_alloc(&rfcomm_tx_pool, K_NO_WAIT);
1042	    if (!nbuf) {
1043	        BT_LOGW("rfcomm_tx_pool exhausted");
1044	        return BT_STATUS_NOMEM;
1045	    }
1046	
1047	    net_buf_reserve(nbuf, SPP_MFS_EXTRA_SIZE - 1); /* exclude trailing FCS byte */
1048	    net_buf_add_mem(nbuf, buf, size);
1049	
1050	    ret = bt_rfcomm_dlc_send(&spp_conn->rfcomm_dlc, nbuf);
1051	    if (ret < 0) {
1052	        BT_LOGE("Failed to send data on RFCOMM DLC: %d", ret);
1053	        net_buf_unref(nbuf);
1054	        return BT_STATUS_FAIL;
1055	    }
1056	
1057	    BT_DUMPBUFFER("SPP TX", buf, size);
1058	
1059	    spp_buf = malloc(sizeof(sal_spp_buffer_t));
1060	    if (!spp_buf) {
1061	        BT_LOGE("Failed to allocate memory for SPP buffer");
1062	        net_buf_unref(nbuf);
1063	        return BT_STATUS_NOMEM;
1064	    }
1065	
1066	    spp_buf->conn_port = conn_port;
1067	    spp_buf->buf = buf;
1068	
1069	    spp_conn_lock();
1070	    bt_list_add_tail(spp_conn->tx_list, spp_buf);
1071	    spp_conn_unlock();
1072	
1073	    return BT_STATUS_SUCCESS;
1074	}
