1084	        spp_conn_unlock();
1085	        BT_LOGE("No SPP connection found for port %d", port);
1086	        return BT_STATUS_PARM_INVALID;
1087	    }
1088	
1089	    if (!accept) {
1090	        bt_rfcomm_dlc_disconnect(&spp_conn->rfcomm_dlc);
1091	        bt_list_remove(spp_mgr->connections, spp_conn);
1092	        spp_conn_unlock();
1093	
1094	        BT_LOGD("SPP connection on port %d rejected", port);
1095	        return BT_STATUS_SUCCESS;
1096	    }
1097	
1098	    spp_conn->conn_port = port;
