533	static sal_spp_connection_t* spp_connection_new(bt_address_t* addr, uint16_t conn_port, uint16_t scn)
534	{
535	    sal_spp_connection_t* spp_conn;
536	
537	    spp_conn = malloc(sizeof(sal_spp_connection_t));
538	    if (!spp_conn) {
539	        BT_LOGE("Failed to allocate memory for SPP connection");
540	        return NULL;
541	    }
542	
543	    memset(spp_conn, 0, sizeof(sal_spp_connection_t));
544	    spp_conn->scn = scn;
545	    spp_conn->conn_port = conn_port;
546	    spp_conn->tx_list = bt_list_new(spp_tx_clean);
547	    if (!spp_conn->tx_list) {
548	        BT_LOGE("Failed to create SPP connection transmission list");
549	        spp_connection_free(spp_conn);
550	        return NULL;
551	    }
552	
553	    spp_conn->rx_list = bt_list_new(spp_rx_buf_free);
554	    if (!spp_conn->rx_list) {
555	        BT_LOGE("Failed to create SPP connection reception list");
556	        spp_connection_free(spp_conn);
557	        return NULL;
558	    }
559	
560	    spp_conn->rfcomm_dlc.ops = &g_rfcomm_ops;
561	    spp_conn->rfcomm_dlc.mtu = SAL_SPP_RFCOMM_MFS;
562	    memcpy(&spp_conn->addr, addr, sizeof(bt_address_t));
563	
564	    return spp_conn;
565	}
