846	static bt_status_t spp_connect_handler(bt_controller_id_t id, bt_address_t* addr, void* user_data)
847	{
848	    sal_spp_manager_t* spp_mgr = &g_spp_manager;
849	    sal_spp_connection_t* spp_conn = (sal_spp_connection_t*)user_data;
850	    struct bt_conn* conn;
851	
852	    BT_LOGD("Initiating SPP connection to addr:%s", bt_addr_str(addr));
853	    spp_on_connection_state_changed(addr, spp_conn->conn_port, PROFILE_STATE_CONNECTING);
854	
855	    conn = bt_conn_lookup_addr_br((bt_addr_t*)addr);
856	    if (!conn) {
857	        BT_LOGE("No ACL connection found for address: %s", bt_addr_str(addr));
858	        goto fail;
859	    }
860	
861	    spp_conn->conn = conn;
862	
863	    if (spp_conn->conn_port & 0x3F) {
864	        int err;
865	
866	        err = spp_connect_with_channel(spp_conn, spp_conn->scn);
867	        if (err < 0) {
868	            BT_LOGE("Failed to connect with scn: %d", err);
869	            goto fail;
870	        }
871	    } else {
872	        int err;
873	
874	        err = spp_connect_with_uuid(spp_conn, &spp_conn->uuid);
875	        if (err < 0) {
876	            BT_LOGE("Failed to connect with uuid, err: %d", err);
877	            goto fail;
878	        }
879	    }
880	
881	    spp_conn_lock();
882	    bt_list_add_tail(spp_mgr->connections, spp_conn);
883	    spp_conn_unlock();
884	
885	    return BT_STATUS_SUCCESS;
