1063	        return BT_STATUS_NOMEM;
1064	    }
1065	
1066	    spp_buf->conn_port = conn_port;
1067	    spp_buf->buf = buf;
1068	
1069	    spp_conn_lock();
1070	    bt_list_add_tail(spp_conn->tx_list, spp_buf);
