1191	{
1192		struct bt_dev *hdev = bt_dev_get(dev_id);
1193	
1194		if (!hdev) {
1195			return -ENODEV;
1196		}
1197	
1198		if (server->psm < L2CAP_BR_PSM_START || !server->accept) {
1199			return -EINVAL;
1200		}
1201	
1202		/* PSM must be odd and lsb of upper byte must be 0 */
1203		if ((server->psm & 0x0101) != 0x0001) {
1204			return -EINVAL;
1205		}
1206	
1207		if (server->sec_level > BT_SECURITY_L4) {
1208			return -EINVAL;
1209		} else if (server->sec_level == BT_SECURITY_L0 &&
1210			   server->psm != L2CAP_BR_PSM_SDP) {
1211			server->sec_level = BT_SECURITY_L1;
1212		}
1213	
1214		/* Check if given PSM is already in use */
1215		if (l2cap_br_server_lookup_psm(hdev, server->psm)) {
1216			LOG_DBG("PSM already registered");
1217			return -EADDRINUSE;
1218		}
1219	
1220		LOG_DBG("PSM 0x%04x", server->psm);
1221	
1222		sys_slist_append(&hdev->l2cap_br_ctx->br_servers, &server->node);
1223	
1224		return 0;
1225	}
